/*
 * A014154  Inverse of 145th cyclotomic polynomial.
 * https://oeis.org/A014154
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy
 * Formula:   a(n) is the coefficient of x^n in the power‑series expansion of
 *            1/Φ_145(x). Φ_145 is the 145th cyclotomic polynomial, of degree
 *            112. The sequence is periodic with period 145. The values are
 *            generated by first computing the coefficients of Φ_145 via a
 *            long division of the polynomials Φ_145(x) = (∑...
 * Range:     i8 n <= 1000, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>

#define PERIOD 145
#define DEGREE 112
#define Q_DEG 32   /* degree of denominator Q(x) = (∑_{i=0}^{4} x^i)(∑_{i=0}^{28} x^i) */

/* Compute the coefficients of Φ_145(x).  The result is stored in the
   static array 'phi_coeff', with phi_coeff[0] = 1 and phi_coeff[DEGREE]
   giving the coefficient of x^DEGREE.  The array is initialized on the
   first call to a(). */
static seq_t phi_coeff[DEGREE + 1];
static bool phi_init = false;

static void init_phi_coeff(void)
{
    seq_t q[Q_DEG + 1] = {0};
    /* Build Q(x) coefficients: Q(x) = (1 + x + x^2 + x^3 + x^4) *
                                   (1 + x + ... + x^28)   */
    for (int i = 0; i <= Q_DEG; ++i) {
        if (i <= 4) {
            q[i] = (seq_t)(i + 1);                /* 1,2,3,4,5           */
        } else if (i <= 28) {
            q[i] = (seq_t)5;                       /* constant 5          */
        } else {
            q[i] = (seq_t)(33 - i);                /* 4,3,2,1             */
        }
    }

    /* Long division:  P(x) = ∑_{i=0}^{144} x^i
       Find R(x) = ∑_{i=0}^{DEGREE} r_i x^i such that R(x) * Q(x) = P(x). */
    phi_coeff[0] = (seq_t)1;  /* r_0 = 1 */
    for (int i = 1; i <= DEGREE; ++i) {
        seq_t sum = 0;
        /* sum_{j=0}^{i-1} phi_coeff[j] * q[i-j] ; q[s] = 0 for s>Q_DEG */
        int j_start = (i > Q_DEG) ? (i - Q_DEG) : 0;   /* j >= i-Q_DEG ensures s<=Q_DEG */
        for (int j = j_start; j <= i - 1; ++j) {
            int s = i - j;               /* s = i - j with 1 <= s <= Q_DEG */
            sum += phi_coeff[j] * q[s];
        }
        /* P_i = 1 for i <= 144; for i > 144, P_i = 0;  but i <= DEGREE=112 < 144 */
        phi_coeff[i] = (seq_t)1 - sum;
    }
    phi_init = true;
}

/* Compute the first PERIOD values of the sequence a(n) using the
   recurrence derived from the coefficients of Φ_145(x).  The values are
   stored in the static array 'period'. */
static seq_t period[PERIOD];
static bool period_init = false;

static void init_period(void)
{
    if (!phi_init) init_phi_coeff();

    period[0] = (seq_t)1;
    for (int n = 1; n < PERIOD; ++n) {
        seq_t sum = 0;
        int k_max = (n < DEGREE) ? n : DEGREE;
        for (int k = 1; k <= k_max; ++k) {
            sum += phi_coeff[k] * period[n - k];
        }
        period[n] = -sum;
    }
    period_init = true;
}

/* ------------------------------------------------------------------------ */

seq_t a(idx_t n)
{
    if (!period_init) init_period();
    idx_t idx = n % (idx_t)PERIOD;
    return period[(int)idx];
}
